data.templates.yaml:
# config file version
apiVersion: 1

# List of templates to import or update
# source https://community.grafana.com/t/working-configuration-example-for-alerts-templating-telegram-and-slack/80988
templates:
  - name: slack
    template: |
      {{/* Slack treats "<...>" as links/mentions and "&" as entity start: unescaped values can swallow the rest of the message */}}
      {{ define "__slack_escape" -}}
        {{- . | reReplaceAll "&" "&amp;" | reReplaceAll "<" "&lt;" | reReplaceAll ">" "&gt;" -}}
      {{- end }}

      {{/* Percent-encode characters that would terminate a Slack <url|text> link early */}}
      {{ define "__slack_url" -}}
        {{- . | reReplaceAll " " "%20" | reReplaceAll "\"" "%22" | reReplaceAll "<" "%3C" | reReplaceAll ">" "%3E" | reReplaceAll "\\|" "%7C" -}}
      {{- end }}

      {{ define "__slack_severity_emoji" -}}
        {{- if eq . "critical" -}}🔥
        {{- else if eq . "warning" -}}⚠️
        {{- else if eq . "info" -}}ℹ️
        {{- else -}}🔔
        {{- end -}}
      {{- end }}

      {{ define "__slack_severity_name" -}}
        {{- if eq . "critical" -}}Critical
        {{- else if eq . "warning" -}}Warning
        {{- else if eq . "info" -}}Info
        {{- else -}}Other
        {{- end -}}
      {{- end }}

      {{/* Single line, e.g. "[mainnet] 🔥 2 firing · ✅ 1 resolved | Some alert" */}}
      {{ define "slack_title" -}}
        {{- $highest := "" -}}
        {{- range .Alerts.Firing -}}
          {{- $s := trimSpace .Annotations.severity -}}
          {{- if eq $s "critical" -}}
            {{- $highest = "critical" -}}
          {{- else if and (eq $s "warning") (ne $highest "critical") -}}
            {{- $highest = "warning" -}}
          {{- else if and (eq $s "info") (eq $highest "") -}}
            {{- $highest = "info" -}}
          {{- end -}}
        {{- end -}}
        [mock]
        {{- if gt (len .Alerts.Firing) 0 }} {{ template "__slack_severity_emoji" $highest }} {{ len .Alerts.Firing }} firing{{ end -}}
        {{- if and (gt (len .Alerts.Firing) 0) (gt (len .Alerts.Resolved) 0) }} ·{{ end -}}
        {{- if gt (len .Alerts.Resolved) 0 }} ✅ {{ len .Alerts.Resolved }} resolved{{ end -}}
        {{- with .CommonLabels.alertname }} | {{ . }}{{ end -}}
      {{- end }}

      {{/* Firing alerts grouped by severity (critical, warning, info, other), followed by resolved alerts */}}
      {{ define "slack_message" -}}
        {{- $firing := .Alerts.Firing -}}
        {{- $first := true -}}
        {{- range $sev := stringSlice "critical" "warning" "info" "" -}}
          {{- $header := false -}}
          {{- range $firing -}}
            {{- $s := trimSpace .Annotations.severity -}}
            {{- $match := eq $s $sev -}}
            {{- if eq $sev "" -}}
              {{- $match = and (ne $s "critical") (ne $s "warning") (ne $s "info") -}}
            {{- end -}}
            {{- if $match -}}
              {{- if not $header -}}
                {{- if not $first }}{{ "\n" }}{{ end -}}
                {{- template "__slack_severity_emoji" $sev }} *{{ template "__slack_severity_name" $sev }}*{{ "\n" -}}
                {{- $header = true -}}
                {{- $first = false -}}
              {{- end -}}
              {{- template "slack_alert_firing" . -}}
            {{- end -}}
          {{- end -}}
        {{- end -}}
        {{- if gt (len .Alerts.Resolved) 0 -}}
          {{- if not $first }}{{ "\n" }}{{ end -}}
          ✅ *Resolved*{{ "\n" -}}
          {{- range .Alerts.Resolved -}}
            {{- template "slack_alert_resolved" . -}}
          {{- end -}}
        {{- end -}}
      {{- end }}

      {{ define "slack_alert_firing" -}}
        • *{{ template "__slack_escape" .Labels.alertname }}*{{ with .Annotations.summary }}: {{ template "__slack_escape" . }}{{ end }}{{ "\n" -}}
        {{- with .Annotations.description }}{{ "    " }}{{ template "__slack_escape" . }}{{ "\n" }}{{ end -}}
        {{- template "__slack_alert_labels" . -}}
        {{ "    " }}Firing since {{ .StartsAt.UTC.Format "2006-01-02 15:04:05 UTC" -}}
        {{- template "__slack_alert_links" . }} · {{ template "slack_gcloud_log_link" . }}{{ "\n" -}}
      {{- end }}

      {{ define "slack_alert_resolved" -}}
        {{- $s := trimSpace .Annotations.severity -}}
        • *{{ template "__slack_escape" .Labels.alertname }}*{{ with .Annotations.summary }}: {{ template "__slack_escape" . }}{{ end }}{{ "\n" -}}
        {{- template "__slack_alert_labels" . -}}
        {{ "    " }}{{ if $s }}Was {{ template "__slack_escape" $s }} · {{ end -}}
        Resolved at {{ .EndsAt.UTC.Format "2006-01-02 15:04:05 UTC" }} after {{ (.EndsAt.Sub .StartsAt).Round 1000000000 -}}
        {{- template "__slack_alert_links" . }}{{ "\n" -}}
      {{- end }}

      {{/* Labels identifying the alert instance, excluding those that are redundant or purely technical */}}
      {{ define "__slack_alert_labels" -}}
        {{- $labels := .Labels.Remove (stringSlice "alertname" "grafana_folder" "gcloud_filter" "priority" "team" "severity") -}}
        {{- if gt (len $labels) 0 -}}
          {{ "    " }}{{ range $i, $p := $labels.SortedPairs }}{{ if $i }} {{ end }}`{{ $p.Name }}={{ template "__slack_escape" (reReplaceAll "`" "'" $p.Value) }}`{{ end }}{{ "\n" -}}
        {{- end -}}
      {{- end }}

      {{ define "__slack_alert_links" -}}
        {{- with .GeneratorURL }} · <{{ template "__slack_url" . }}|Alert rule>{{ end -}}
        {{- if .PanelURL }} · <{{ template "__slack_url" .PanelURL }}|Panel>{{ else if .DashboardURL }} · <{{ template "__slack_url" .DashboardURL }}|Dashboard>{{ end -}}
        {{- with .Annotations.runbook_url }} · <{{ template "__slack_url" . }}|Runbook>{{ end -}}
        {{- if eq .Status "firing" }}{{ with .SilenceURL }} · <{{ template "__slack_url" . }}|Silence>{{ end }}{{ end -}}
      {{- end }}

      {{ define "slack_gcloud_log_link" }}<https://console.cloud.google.com/logs/query;startTime={{ (.StartsAt.Add -600000000000).UTC.Format "2006-01-02T15:04:05Z"  }};endTime={{ (.StartsAt.Add 600000000000).UTC.Format "2006-01-02T15:04:05Z"  }};query={{ if ne .Labels.gcloud_filter_skip_cluster "true" }}resource.labels.cluster_name%3D%22cn-mocknet%22%0A{{ end }}{{ template "__slack_url" .Labels.gcloud_filter }}?project=da-cn-devnet|Logs>{{ end }}

      {{ define "slack_color" -}}
        {{ $hasCritical := false }}{{ $hasWarning := false }}{{ $hasInfo := false }}{{ $hasOthers := false }}
        {{- range .Alerts.Firing -}}
          {{- if eq .Annotations.severity "critical" -}}
            {{- $hasCritical = true -}}
          {{- else if eq .Annotations.severity "warning" -}}
            {{- $hasWarning = true -}}
          {{- else if eq .Annotations.severity "info" -}}
            {{- $hasInfo = true -}}
          {{- else -}}
            {{- $hasOthers = true -}}
          {{- end -}}
        {{- end -}}
        {{ if eq .Status "firing" -}}
          {{ if $hasCritical -}}
            danger
          {{- else if $hasWarning -}}
            warning
          {{- else -}}
            #439FE0
          {{- end -}}
        {{ else -}}
          good
        {{- end }}
      {{- end }}

      {{ define "support_email_message" }}
      [ MAINNET-DA2-SVN-CRITICAL-ALERT 9f2b7e1a-4c3d-58b9-9f1e-df9c4a5b6e7d ]
      {{ if gt (len .Alerts.Firing) 0 }}**Firing**
      {{ template "__text_alert_list" .Alerts.Firing }}{{ if gt (len .Alerts.Resolved) 0 }}
      {{ end }}{{ end }}{{ if gt (len .Alerts.Resolved) 0 }}**Resolved**
      {{ template "__text_alert_list" .Alerts.Resolved }}{{ end }}{{ end }}
